 stable=O/'stable_actor';stable.mkdir(exist_ok=True);shutil.copy2(V/'qualified_actor.pt',stable/'qualified_student_fallback.pt');shutil.copy2(Path(best['NATIVE']['checkpoint'])/'actor.pt',stable/'confirmed_native_actor.pt');save('STABLE_ACTOR.json',dict(qualified_student_fallback=str(stable/'qualified_student_fallback.pt'),confirmed_native_actor=str(stable/'confirmed_native_actor.pt'),confirmed_source=best['NATIVE']['checkpoint'],frozen=True,deterministic_native_only=True,stochastic_safety_not_established=True,matched_ineligible=True,execution_takeover=False,latest_10k_candidate_not_promoted=True))
 episodes=[json.loads(x) for x in (L/'EPISODES.jsonl').read_text().splitlines()];full=[x for x in episodes if x.get('episode_dir')];fails=[x for x in full if not x['complete']];curve=list(csv.DictReader((L/'LEARNING_CURVE.csv').open()));grad=read('GRADIENT_SCALE_AUDIT.json');units=read('EXPLORATION_UNITS_CORRECTED.json');critic=read('CRITIC_DIAGNOSTIC_after.json');beforecritic=read('CRITIC_DIAGNOSTIC_before.json');cfgsha=sha(L/'PREREGISTRATION.json');assert cfgsha==read('LOCK.json')['config'];wall=(time.time()-read('STATE.json')['started_unix'])/3600
 summary=dict(STATUS='PAUSED_RESOURCE_RISK',pause_reason='NEW_SWAP_OVER_128_MIB',RNG_ISOLATION='PASS',TRANSITIONS='PASS',PRESERVATION='PASS',configuration=cfg,configuration_sha256=cfgsha,TOTAL_ONLINE_STEPS=21283,initial_frozen_collection_steps=11283,actor_online_collection_steps=10000,EVALUATION_ONLY_STEPS=final['evaluation_only_steps'],rescues=0,attempts=1,critic_updates=30010,actor_updates=1010,best=best,latest_native_candidate=compact(latest),latest_matched=compact(matched),latest_stochastic=compact(stochastic),latest_best_confirmation_pending=True,claim_levels=levels,confirmed_best_jf=bn['J_F'],latest_candidate_jf=latest['J_F'],confirmed_improvement_percent=100*(student['J_F']-bn['J_F'])/student['J_F'],candidate_improvement_percent=100*(student['J_F']-latest['J_F'])/student['J_F'],confirmed_gap_to_strong_native=bn['J_F']-strong['J_F'],candidate_gap_to_strong_native=latest['J_F']-strong['J_F'],complete_online_episodes=len(full),failed_online_episodes=len(fails),negative_evaluations=len(negative),resources=resources,wall_hours_at_evidence_closeout=wall,training_pause_wall_hours=pause['wall_s']/3600,resumable_checkpoint=pause['resumable_checkpoint'])
